function narrowDirectionExperienceFamily(
  value: string | undefined,
): DirectionCandidate['experienceFamily'] | undefined {
  switch (value) {
    case 'social':
    case 'cultural':
    case 'playful':
    case 'intimate':
    case 'exploratory':
    case 'ambient':
    case 'eventful':
    case 'ritual':
    case 'indulgent':
      return value
    default:
      return undefined
  }
}

