function isDiagnosticPreferredWindDownCategory(
  category: BuiltScenarioStop['venueCategory'],
): boolean {
  return (
    category === 'restaurant' ||
    category === 'bar' ||
    category === 'cafe' ||
    category === 'dessert'
  )
}

function isDiagnosticDisallowedWindDownCategory(
  category: BuiltScenarioStop['venueCategory'],
): boolean {
  return (
    category === 'event' ||
    category === 'museum' ||
    category === 'activity' ||
    category === 'live_music'
  )
}

function evaluateDiagnosticWindDownEligibility(params: {
  stop: BuiltScenarioStop | undefined
  contractConstraints?: ContractConstraints
}): {
  wouldPassGenericWindDownEligibility: boolean
  rejectionReason: string
  missingCategory: boolean
  missingRoleFit: boolean
  noisyEventLikeCategory: boolean
  hasPerformanceOrEventSignals: boolean
} {
  const { stop, contractConstraints } = params
  if (!stop) {
    return {
      wouldPassGenericWindDownEligibility: false,
      rejectionReason: 'missing_stop',
      missingCategory: true,
      missingRoleFit: true,
      noisyEventLikeCategory: false,
      hasPerformanceOrEventSignals: false,
    }
  }
  const category = stop.venueCategory
  const roleFitWindDown = stop.roleFit.windDown
  const roleFitHighlight = stop.roleFit.highlight
  const missingCategory = !category
  const missingRoleFit = typeof roleFitWindDown !== 'number' || typeof roleFitHighlight !== 'number'
  const noisyEventLikeCategory =
    category === 'event' || category === 'live_music' || category === 'activity'
  const hasPerformanceOrEventSignals =
    (stop.eventPotential ?? 0) >= 0.58 || (stop.performancePotential ?? 0) >= 0.66
  const isPreferredCategory = isDiagnosticPreferredWindDownCategory(category)

  if (isDiagnosticDisallowedWindDownCategory(category)) {
    return {
      wouldPassGenericWindDownEligibility: false,
      rejectionReason: 'category_disallowed',
      missingCategory,
      missingRoleFit,
      noisyEventLikeCategory,
      hasPerformanceOrEventSignals,
    }
  }
  if (stop.sourceType === 'event') {
    return {
      wouldPassGenericWindDownEligibility: false,
      rejectionReason: 'sourceType_event',
      missingCategory,
      missingRoleFit,
      noisyEventLikeCategory,
      hasPerformanceOrEventSignals,
    }
  }
  if (hasPerformanceOrEventSignals) {
    return {
      wouldPassGenericWindDownEligibility: false,
      rejectionReason: 'performance_or_event_signal',
      missingCategory,
      missingRoleFit,
      noisyEventLikeCategory,
      hasPerformanceOrEventSignals,
    }
  }
  if ((roleFitWindDown ?? 0) < 0.5) {
    return {
      wouldPassGenericWindDownEligibility: false,
      rejectionReason: 'roleFitWindDown_below_min',
      missingCategory,
      missingRoleFit,
      noisyEventLikeCategory,
      hasPerformanceOrEventSignals,
    }
  }
  if (!isPreferredCategory && (roleFitWindDown ?? 0) < 0.62) {
    return {
      wouldPassGenericWindDownEligibility: false,
      rejectionReason: 'non_preferred_category_roleFitWindDown_below_min',
      missingCategory,
      missingRoleFit,
      noisyEventLikeCategory,
      hasPerformanceOrEventSignals,
    }
  }
  if ((roleFitHighlight ?? 0) >= (roleFitWindDown ?? 0) + 0.12) {
    return {
      wouldPassGenericWindDownEligibility: false,
      rejectionReason: 'highlight_dominates_windDown',
      missingCategory,
      missingRoleFit,
      noisyEventLikeCategory,
      hasPerformanceOrEventSignals,
    }
  }
  if (
    contractConstraints?.windDownStrictness === 'soft_required' &&
    (roleFitWindDown ?? 0) < (isPreferredCategory ? 0.56 : 0.64)
  ) {
    return {
      wouldPassGenericWindDownEligibility: false,
      rejectionReason: 'soft_required_threshold_failure',
      missingCategory,
      missingRoleFit,
      noisyEventLikeCategory,
      hasPerformanceOrEventSignals,
    }
  }
  return {
    wouldPassGenericWindDownEligibility: true,
    rejectionReason: 'passes',
    missingCategory,
    missingRoleFit,
    noisyEventLikeCategory,
    hasPerformanceOrEventSignals,
  }
}

function scoreSurpriseContrastWindDownRepairCandidate(stop: BuiltScenarioStop): number {
  let score = stop.roleFit.windDown ?? 0
  if (stop.stopType === 'atmospheric_nightcap') {
    score += 0.24
  } else if (stop.stopType === 'performance_or_fine_dining') {
    score += 0.08
  }
  if (stop.position === 'closer') {
    score += 0.12
  } else if (stop.position === 'windDown') {
    score += 0.09
  }
  if (isDiagnosticPreferredWindDownCategory(stop.venueCategory)) {
    score += 0.14
  }
  score += (stop.currentRelevance ?? 0) * 0.08
  score += (stop.authorityScore ?? 0) * 0.08
  return score
}

function repairSurpriseContrastWindDownOpportunity(params: {
  opportunity: VerifiedCityOpportunity
  contractConstraints?: ContractConstraints
}): {
  opportunity: VerifiedCityOpportunity
  repairApplied: boolean
  repairedCandidate?: BuiltScenarioStop
} {
  const { opportunity, contractConstraints } = params
  if (opportunity.scenarioWindDownDebug?.finalRoleEligible !== false || !opportunity.scenarioNight) {
    return {
      opportunity,
      repairApplied: false,
    }
  }
  const scenarioNight = opportunity.scenarioNight
  const startVenueId =
    scenarioNight.stops.find((stop) => stop.position === 'start')?.venueId ??
    scenarioNight.stops[0]?.venueId ??
    null
  const highlightVenueId =
    scenarioNight.stops.find((stop) => stop.position === 'highlight')?.venueId ?? null
  const failedWindDownVenueId = opportunity.scenarioWindDownDebug.originalVenueId ?? null
  const repairCandidates = scenarioNight.stops
    .filter((stop) => stop.venueId !== startVenueId)
    .filter((stop) => stop.venueId !== highlightVenueId)
    .filter((stop) => stop.venueId !== failedWindDownVenueId)
    .map((stop) => ({
      stop,
      diagnostic: evaluateDiagnosticWindDownEligibility({
        stop,
        contractConstraints,
      }),
    }))
    .filter((entry) => entry.diagnostic.wouldPassGenericWindDownEligibility)
    .sort(
      (left, right) =>
        scoreSurpriseContrastWindDownRepairCandidate(right.stop) -
          scoreSurpriseContrastWindDownRepairCandidate(left.stop) ||
        left.stop.name.localeCompare(right.stop.name),
    )
  const repairedCandidate = repairCandidates[0]?.stop
  if (!repairedCandidate) {
    return {
      opportunity,
      repairApplied: false,
    }
  }

  const repairedCloses: CityOpportunityStopOption[] = [
    {
      venueId: repairedCandidate.venueId,
      name: repairedCandidate.name,
      address: repairedCandidate.address,
      reason:
        repairedCandidate.whyThisStop ||
        repairedCandidate.reasons[0] ||
        'Strong repaired scenario landing.',
      score:
        repairedCandidate.roleFit.windDown ??
        repairedCandidate.authorityScore ??
        opportunity.closes[0]?.score ??
        0.62,
    },
    ...opportunity.closes.filter((stop) => stop.venueId !== repairedCandidate.venueId),
  ].slice(0, 4)

  return {
    opportunity: {
      ...opportunity,
      closes: repairedCloses,
      storySpine: {
        ...opportunity.storySpine,
        windDown: repairedCandidate.name,
      },
      scenarioWindDownDebug: {
        ...opportunity.scenarioWindDownDebug,
        repairApplied: true,
        repairReplacementVenueId: repairedCandidate.venueId,
        repairReplacementName: repairedCandidate.name,
        repairSource: 'surprise_contrast_same_scenario_candidate',
        repairReason: 'pre_artifact_windDown_repair',
        finalVenueId: repairedCandidate.venueId,
        finalName: repairedCandidate.name,
        finalRoleEligible: true,
      },
    },
    repairApplied: true,
    repairedCandidate,
  }
}

function selectSurpriseScenarioBackedArtifactSourceOpportunities(params: {
  opportunities: VerifiedCityOpportunity[]
  primaryFamily: ScenarioFamily | null
  contrastFamily: ScenarioFamily | null
  crossPersonaFamily?: ScenarioFamily | null
  maxCount?: number
}): VerifiedCityOpportunity[] {
  const {
    opportunities,
    primaryFamily,
    contrastFamily,
    crossPersonaFamily = null,
    maxCount = 5,
  } = params
  if (maxCount <= 0 || opportunities.length === 0) {
    return []
  }
  if (!contrastFamily && !crossPersonaFamily) {
    return opportunities.slice(0, maxCount)
  }

  const getOpportunityFamily = (opportunity: VerifiedCityOpportunity): string | null =>
    opportunity.scenarioNight?.scenarioFamily ??
    deriveScenarioFamilyHintFromOpportunity({
      opportunityId: opportunity.id,
      flavor: opportunity.flavor,
    })
  const primaryOpportunities = opportunities.filter(
    (opportunity) => getOpportunityFamily(opportunity) === primaryFamily,
  )
  const contrastOpportunities = opportunities.filter(
    (opportunity) => getOpportunityFamily(opportunity) === contrastFamily,
  )
  const crossPersonaOpportunities = opportunities.filter(
    (opportunity) => getOpportunityFamily(opportunity) === crossPersonaFamily,
  )
  if (contrastOpportunities.length === 0 && crossPersonaOpportunities.length === 0) {
    return opportunities.slice(0, maxCount)
  }

  const selected: VerifiedCityOpportunity[] = []
  const selectedIds = new Set<string>()
  const pushOpportunity = (opportunity: VerifiedCityOpportunity | undefined) => {
    if (!opportunity || selectedIds.has(opportunity.id) || selected.length >= maxCount) {
      return
    }
    selected.push(opportunity)
    selectedIds.add(opportunity.id)
  }
  const preferredContrastOpportunity =
    contrastOpportunities.find((opportunity) => opportunity.scenarioWindDownDebug?.finalRoleEligible) ??
    contrastOpportunities[0]
  const preferredCrossPersonaOpportunity =
    crossPersonaOpportunities.find(
      (opportunity) => opportunity.scenarioWindDownDebug?.finalRoleEligible,
    ) ?? crossPersonaOpportunities[0]
  const reservedSlots =
    (preferredContrastOpportunity ? 1 : 0) + (preferredCrossPersonaOpportunity ? 1 : 0)

  primaryOpportunities
    .slice(0, Math.max(0, maxCount - reservedSlots))
    .forEach(pushOpportunity)
  pushOpportunity(preferredContrastOpportunity)
  pushOpportunity(preferredCrossPersonaOpportunity)
  opportunities.forEach(pushOpportunity)
  return selected
}

function getDirectionResolverPocketKey(card: RealityDirectionCard): string {
  return card.debugMeta?.pocketId ?? card.id
}

function rankDirectionResolverCards(cards: RealityDirectionCard[]): RealityDirectionCard[] {
  return cards.slice().sort((left, right) => {
    const leftScore = left.debugMeta?.confidence ?? 0
    const rightScore = right.debugMeta?.confidence ?? 0
    if (rightScore !== leftScore) {
      return rightScore - leftScore
    }
    return left.id.localeCompare(right.id)
  })
}

function resolveDirectionCardById(
  directionId: string | null | undefined,
  directionCards: RealityDirectionCard[],
  allDirectionCards: RealityDirectionCard[],
): RealityDirectionCard | null {
  if (!directionId) {
    return null
  }
  return (
    directionCards.find((entry) => entry.id === directionId) ??
    allDirectionCards.find((entry) => entry.id === directionId) ??
    null
  )
}

function resolveDirectionCardByPocketId(
  pocketId: string | null | undefined,
  directionCards: RealityDirectionCard[],
  allDirectionCards: RealityDirectionCard[],
): RealityDirectionCard | null {
  if (!pocketId) {
    return null
  }
  return (
    directionCards.find((entry) => getDirectionResolverPocketKey(entry) === pocketId) ??
    allDirectionCards.find((entry) => getDirectionResolverPocketKey(entry) === pocketId) ??
    null
  )
}

function resolveDirectionCardForArtifactWithTrace(params: {
  directionCards: RealityDirectionCard[]
  allDirectionCards: RealityDirectionCard[]
  directionId?: string | null
  pocketId?: string | null
  allowPocketFallbackOnUnmatchedDirectionId?: boolean
}): {
  direction: RealityDirectionCard | null
  directionIdMatched: boolean
  pocketFallbackMatched: boolean
  resolvedDirectionId: string | null
  fallbackDirectionCandidateId: string | null
  resolveDirectionFailureReason: string | null
} {
  const {
    directionCards,
    allDirectionCards,
    directionId,
    pocketId,
    allowPocketFallbackOnUnmatchedDirectionId,
  } = params
  const directionById = resolveDirectionCardById(directionId, directionCards, allDirectionCards)
  if (directionById) {
    return {
      direction: directionById,
      directionIdMatched: true,
      pocketFallbackMatched: false,
      resolvedDirectionId: directionById.id,
      fallbackDirectionCandidateId: null,
      resolveDirectionFailureReason: null,
    }
  }
  if (directionId && allowPocketFallbackOnUnmatchedDirectionId && pocketId) {
    const directionByPocket = resolveDirectionCardByPocketId(pocketId, directionCards, allDirectionCards)
    if (directionByPocket) {
      return {
        direction: directionByPocket,
        directionIdMatched: false,
        pocketFallbackMatched: true,
        resolvedDirectionId: directionByPocket.id,
        fallbackDirectionCandidateId: directionByPocket.id,
        resolveDirectionFailureReason: 'direction_id_unmatched_pocket_fallback_used',
      }
    }
  }
  if (!directionId && pocketId) {
    const directionByPocket = resolveDirectionCardByPocketId(pocketId, directionCards, allDirectionCards)
    if (directionByPocket) {
      return {
        direction: directionByPocket,
        directionIdMatched: false,
        pocketFallbackMatched: true,
        resolvedDirectionId: directionByPocket.id,
        fallbackDirectionCandidateId: directionByPocket.id,
        resolveDirectionFailureReason: null,
      }
    }
  }
  const fallbackDirection = directionCards[0] ?? allDirectionCards[0] ?? null
  if (fallbackDirection && !directionId && !pocketId) {
    return {
      direction: fallbackDirection,
      directionIdMatched: false,
      pocketFallbackMatched: false,
      resolvedDirectionId: fallbackDirection.id,
      fallbackDirectionCandidateId: fallbackDirection.id,
      resolveDirectionFailureReason: null,
    }
  }
  return {
    direction: null,
    directionIdMatched: false,
    pocketFallbackMatched: false,
    resolvedDirectionId: null,
    fallbackDirectionCandidateId: null,
    resolveDirectionFailureReason: directionId
      ? 'direction_id_unmatched'
      : pocketId
        ? 'pocket_id_unmatched'
        : 'no_direction_or_pocket',
  }
}

function repairSurpriseContrastSelectionContext(params: {
  opportunity: VerifiedCityOpportunity
  directionCards: RealityDirectionCard[]
  allDirectionCards: RealityDirectionCard[]
  districtDiscoveryCards: Array<{ id: string; name: string }>
}): {
  opportunity: VerifiedCityOpportunity
  selectionRepairApplied: boolean
  repairedSelectionDirectionId: string | null
  repairedSelectionPocketId: string | null
  selectionRepairReason: string | null
  matchedDistrictId: string | null
  matchedDirectionId: string | null
  fallbackSelectionCandidate: string | null
  selectionRepairResolverTrace: string
  sourceOpportunitySelection: string
  scenarioSelectionContext: string
} {
  const { opportunity, directionCards, allDirectionCards, districtDiscoveryCards } = params
  const hasLooseTextMatch = (source: string | undefined | null, target: string | undefined | null) => {
    const normalizedSource = normalizeQualityText(source ?? undefined)
    const normalizedTarget = normalizeQualityText(target ?? undefined)
    if (!normalizedSource || !normalizedTarget) {
      return false
    }
    return (
      normalizedSource === normalizedTarget ||
      normalizedSource.includes(normalizedTarget) ||
      normalizedTarget.includes(normalizedSource)
    )
  }
  const originalDirectionId = opportunity.selection.directionId ?? null
  const originalPocketId = opportunity.selection.pocketId ?? null
  const originalResolution = resolveDirectionCardForArtifactWithTrace({
    directionCards,
    allDirectionCards,
    directionId: originalDirectionId,
    pocketId: originalPocketId,
    allowPocketFallbackOnUnmatchedDirectionId: true,
  })
  const scenarioHighlightDistrict =
    opportunity.scenarioNight?.stops.find((stop) => stop.position === 'highlight')?.district ?? null
  const districtHints = dedupeStringIds(
    [
      opportunity.districtContext.primaryDistrict,
      opportunity.anchor.district,
      scenarioHighlightDistrict,
    ].filter((value): value is string => Boolean(value && value.trim())),
  )
  const matchedDistrict =
    (originalPocketId
      ? districtDiscoveryCards.find((district) => district.id === originalPocketId) ?? null
      : null) ??
    districtHints
      .flatMap((hint) =>
        districtDiscoveryCards.filter((district) => hasLooseTextMatch(district.name, hint)),
      )[0] ??
    null
  const matchedDistrictId = matchedDistrict?.id ?? null
  const matchedDistrictName = matchedDistrict?.name ?? districtHints[0] ?? null
  const labelMatchedDirections = matchedDistrictName
    ? rankDirectionResolverCards(
        allDirectionCards.filter((card) => {
          const summary = card.debugMeta?.directionDistrictSupportSummary ?? ''
          return hasLooseTextMatch(summary, matchedDistrictName)
        }),
      )
    : []
  const labelMatchedDirectionIds = labelMatchedDirections.map((card) => card.id)
  const fallbackCandidate =
    (originalResolution.direction
      ? {
          direction: originalResolution.direction,
          pocketKey: getDirectionResolverPocketKey(originalResolution.direction),
          reason: originalResolution.directionIdMatched
            ? 'existing_direction_resolved'
            : 'existing_pocket_resolved',
        }
      : null) ??
    (labelMatchedDirections[0]
      ? {
          direction: labelMatchedDirections[0],
          pocketKey: getDirectionResolverPocketKey(labelMatchedDirections[0]),
          reason: 'district_label_direction_support_match',
        }
      : null)
  const sourceOpportunitySelection = [
    `opportunity=${opportunity.id}`,
    `directionId=${originalDirectionId ?? 'n/a'}`,
    `pocketId=${originalPocketId ?? 'n/a'}`,
  ].join('|')
  const scenarioSelectionContext = [
    `opportunity=${opportunity.id}`,
    `primaryDistrict=${opportunity.districtContext.primaryDistrict ?? 'n/a'}`,
    `anchorDistrict=${opportunity.anchor.district ?? 'n/a'}`,
    `highlightDistrict=${scenarioHighlightDistrict ?? 'n/a'}`,
    `matchedDistrictId=${matchedDistrictId ?? 'n/a'}`,
    `matchedDistrictName=${matchedDistrictName ?? 'n/a'}`,
  ].join('|')
  const selectionRepairResolverTrace = [
    `opportunityId=${opportunity.id}`,
    `originalDirectionId=${originalDirectionId ?? 'n/a'}`,
    `originalPocketId=${originalPocketId ?? 'n/a'}`,
    `resolvedDirectionById=${originalResolution.directionIdMatched ? originalResolution.resolvedDirectionId ?? 'n/a' : 'n/a'}`,
    `resolvedDirectionByPocket=${originalResolution.pocketFallbackMatched ? originalResolution.resolvedDirectionId ?? 'n/a' : 'n/a'}`,
    `matchedPocketKey=${originalResolution.direction ? getDirectionResolverPocketKey(originalResolution.direction) : 'n/a'}`,
    `labelMatchedDirectionIds=${labelMatchedDirectionIds.join(',') || 'none'}`,
    `chosenFallbackCandidate=${fallbackCandidate ? `${fallbackCandidate.direction.id}|${fallbackCandidate.pocketKey}|${fallbackCandidate.reason}` : 'none'}`,
    `failureReason=${fallbackCandidate ? 'none' : originalResolution.resolveDirectionFailureReason ?? 'no_resolvable_selection_candidate'}`,
  ].join('|')

  if (!fallbackCandidate) {
    return {
      opportunity,
      selectionRepairApplied: false,
      repairedSelectionDirectionId: originalDirectionId,
      repairedSelectionPocketId: originalPocketId,
      selectionRepairReason: 'no_resolvable_selection_candidate',
      matchedDistrictId,
      matchedDirectionId: null,
      fallbackSelectionCandidate: null,
      selectionRepairResolverTrace,
      sourceOpportunitySelection,
      scenarioSelectionContext,
    }
  }

  const repairedDirectionId = fallbackCandidate.direction.id
  const repairedPocketId = fallbackCandidate.pocketKey
  const selectionAlreadyResolvable =
    originalDirectionId === repairedDirectionId && originalPocketId === repairedPocketId
  return {
    opportunity: selectionAlreadyResolvable
      ? opportunity
      : {
          ...opportunity,
          selection: {
            pocketId: repairedPocketId,
            directionId: repairedDirectionId,
          },
        },
    selectionRepairApplied: !selectionAlreadyResolvable,
    repairedSelectionDirectionId: repairedDirectionId,
    repairedSelectionPocketId: repairedPocketId,
    selectionRepairReason: selectionAlreadyResolvable
      ? 'selection_already_resolvable'
      : fallbackCandidate.reason,
    matchedDistrictId,
    matchedDirectionId: repairedDirectionId,
    fallbackSelectionCandidate: `${repairedDirectionId}|${repairedPocketId}|${fallbackCandidate.reason}`,
    selectionRepairResolverTrace,
    sourceOpportunitySelection,
    scenarioSelectionContext,
  }
}

function getDeterministicContrastScenarioFamily(
  primaryFamily: ScenarioFamily | null,
): ScenarioFamily | null {
  if (!primaryFamily) {
    return null
  }
  const contrastByPrimaryFamily: Record<ScenarioFamily, ScenarioFamily> = {
    romantic_cozy: 'romantic_cultured',
    romantic_lively: 'romantic_cultured',
    romantic_cultured: 'romantic_lively',
    friends_cozy: 'friends_lively',
    friends_lively: 'friends_cultured',
    friends_cultured: 'friends_lively',
    family_cozy: 'family_cultured',
    family_lively: 'family_cultured',
    family_cultured: 'family_lively',
  }
  return contrastByPrimaryFamily[primaryFamily] ?? null
}

function getDeterministicCrossPersonaScenarioFamily(
  primaryFamily: ScenarioFamily | null,
): ScenarioFamily | null {
  if (!primaryFamily) {
    return null
  }
  const crossPersonaByPrimaryFamily: Record<ScenarioFamily, ScenarioFamily> = {
    romantic_cozy: 'friends_cozy',
    romantic_lively: 'friends_lively',
    romantic_cultured: 'friends_cultured',
    friends_cozy: 'romantic_cozy',
    friends_lively: 'romantic_lively',
    friends_cultured: 'romantic_cultured',
    family_cozy: 'friends_cozy',
    family_lively: 'friends_lively',
    family_cultured: 'friends_cultured',
  }
  return crossPersonaByPrimaryFamily[primaryFamily] ?? null
}

function getScenarioFamilyVibeAnchor(family: ScenarioFamily | null): VibeAnchor | null {
  if (!family) {
    return null
  }
  if (family.endsWith('_cozy')) {
    return 'cozy'
  }
  if (family.endsWith('_lively')) {
    return 'lively'
  }
  if (family.endsWith('_cultured')) {
    return 'cultured'
  }
  return null
}

function getScenarioFamilyVibeLabel(family: ScenarioFamily | null): string | null {
  if (!family) {
    return null
  }
  if (family.endsWith('_cozy')) {
    return 'Cozy'
  }
  if (family.endsWith('_lively')) {
    return 'Lively'
  }
  if (family.endsWith('_cultured')) {
    return 'Cultured'
  }
  return null
}

type CoreTasteRole = Extract<UserStopRole, 'start' | 'highlight' | 'windDown'>
const coreTasteRoles: CoreTasteRole[] = ['start', 'highlight', 'windDown']

interface TasteRoleEligibilitySnapshot {
  score: number
  floor: number
  passed: boolean
  reason: string
}

interface TasteVenuePersonalityProfile {
  intimate: boolean
  social: boolean
  destination: boolean
  lingering: boolean
  quickStop: boolean
  experiential: boolean
  calm: boolean
  highIntensity: boolean
  lowFriction: boolean
  summary: string
}

interface TasteCandidateQualification {
  candidateId: string
  highlightQualificationScore: number
  highlightQualificationPassed: boolean
  roleEligibility: Record<CoreTasteRole, TasteRoleEligibilitySnapshot>
  venuePersonality: TasteVenuePersonalityProfile
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null
}

function isTasteRoleEligibilitySnapshot(value: unknown): value is TasteRoleEligibilitySnapshot {
  if (!isRecord(value)) {
    return false
  }
  return (
    typeof value.score === 'number' &&
    typeof value.floor === 'number' &&
    typeof value.passed === 'boolean' &&
    typeof value.reason === 'string'
  )
}

function isTasteVenuePersonalityProfile(value: unknown): value is TasteVenuePersonalityProfile {
  if (!isRecord(value)) {
    return false
  }
  return (
    typeof value.intimate === 'boolean' &&
    typeof value.social === 'boolean' &&
    typeof value.destination === 'boolean' &&
    typeof value.lingering === 'boolean' &&
    typeof value.quickStop === 'boolean' &&
    typeof value.experiential === 'boolean' &&
    typeof value.calm === 'boolean' &&
    typeof value.highIntensity === 'boolean' &&
    typeof value.lowFriction === 'boolean' &&
    typeof value.summary === 'string'
  )
}

function isTasteCandidateQualification(value: unknown): value is TasteCandidateQualification {
  if (!isRecord(value)) {
    return false
  }
  const roleEligibility = value.roleEligibility
  return (
    typeof value.candidateId === 'string' &&
    typeof value.highlightQualificationScore === 'number' &&
    typeof value.highlightQualificationPassed === 'boolean' &&
    isRecord(roleEligibility) &&
    coreTasteRoles.every((role) => isTasteRoleEligibilitySnapshot(roleEligibility[role])) &&
    isTasteVenuePersonalityProfile(value.venuePersonality)
  )
}

function normalizeTasteCandidateQualificationRecord(
  value: Record<string, unknown>,
): Record<string, TasteCandidateQualification> {
  const normalized: Record<string, TasteCandidateQualification> = {}
  for (const [candidateId, qualification] of Object.entries(value)) {
    if (isTasteCandidateQualification(qualification)) {
      normalized[candidateId] = qualification
    }
  }
  return normalized
}

interface StrongCurationTasteBias {
  highlightFloor: number
  startFloor: number
  windDownFloor: number
  summary: string
}

interface TasteCurationDebug {
  highlightQualificationScore: number | null
  highlightQualificationPassed: boolean | null
  tasteRoleEligibilityByRole: Record<CoreTasteRole, string>
  personaVibeTasteBiasSummary: string
  venuePersonalitySummary: string
  thinPoolHighlightFallbackApplied: boolean
  highlightPoolCountBefore: number
  highlightPoolCountAfter: number
  rolePoolCountByRoleBefore: Record<CoreTasteRole, number>
  rolePoolCountByRoleAfter: Record<CoreTasteRole, number>
  signatureHighlightShortlistCount: number
  signatureHighlightShortlistIds: string[]
  highlightShortlistScoreSummary: string
  selectedHighlightFromShortlist: boolean
  selectedHighlightShortlistRank: number | null
  fallbackToQualifiedHighlightPool: boolean
  upstreamPoolSelectionApplied: boolean
  postGenerationRepairCount: number
  rolePoolVenueIdsByRole: Record<CoreTasteRole, string[]>
  rolePoolVenueIdsCombined: string[]
  thinPoolRelaxationTrace: StrongCurationTastePassResult['thinPoolRelaxationTrace']
}

interface StageOverlapFingerprint {
  scenarioKey: string
  topPocketIds: string[]
  directionCandidatePocketIds: string[]
  retrievedVenueIds: string[]
  rolePoolVenueIds: string[]
  highlightShortlistIds: string[]
  finalStopVenueIds: string[]
}

interface SignatureHighlightShortlistEntry {
  candidate: ScoredVenue
  score: number
}

function buildVisibleNightFingerprint(params: {
  routeTitle?: string
  routeSummary?: string
  flavorLine?: string
  traits?: string[]
  proofLines?: string[]
  districtAnchorLine?: string
  stops?: string[]
  stopVenueIds?: string[]
}): string {
  const normalize = (value?: string): string =>
    value
      ?.trim()
      .toLowerCase()
      .replace(/\s+/g, ' ') ?? ''
  const normalizeList = (values?: string[]): string =>
    (values ?? [])
      .map((value) => normalize(value))
      .filter(Boolean)
      .join('|')
  return [
    normalize(params.routeTitle),
    normalize(params.routeSummary),
    normalize(params.flavorLine),
    normalizeList(params.traits),
    normalizeList(params.proofLines),
    normalize(params.districtAnchorLine),
    normalizeList(params.stops),
    normalizeList(params.stopVenueIds),
  ].join('::')
}

function deriveScenarioFamilyHintFromArtifactIdentity(input: {
  artifactId?: string | null
  sourceOpportunityId?: string | null
  routeTitle?: string | null
}): string | null {
  const corpus = [input.artifactId, input.sourceOpportunityId, input.routeTitle]
    .filter((value): value is string => Boolean(value && value.trim()))
    .join(' ')
    .toLowerCase()
  const builtFamilyMatch = corpus.match(/built_([a-z]+_[a-z]+)(?:_|$)/)
  if (builtFamilyMatch?.[1]) {
    return builtFamilyMatch[1]
  }
  const familyTokenMatch = corpus.match(
    /\b(romantic_(?:cozy|lively|cultured)|friends_(?:cozy|lively|cultured)|family_(?:cozy|lively|cultured))\b/,
  )
  return familyTokenMatch?.[1] ?? null
}

function deriveScenarioFamilyHintFromOpportunity(input: {
  opportunityId?: string | null
  flavor?: string | null
}): string | null {
  return deriveScenarioFamilyHintFromArtifactIdentity({
    artifactId: input.opportunityId,
    sourceOpportunityId: input.opportunityId,
    routeTitle: input.flavor,
  })
}

function summarizeDiagnosticCounts(values: Array<string | null | undefined>): string {
  const counts = new Map<string, number>()
  values.forEach((value) => {
    const normalized = value?.trim()
    if (!normalized) {
      return
    }
    counts.set(normalized, (counts.get(normalized) ?? 0) + 1)
  })
  if (counts.size === 0) {
    return 'none'
  }
  return [...counts.entries()]
    .sort((left, right) => right[1] - left[1] || left[0].localeCompare(right[0]))
    .map(([value, count]) => `${value}:${count}`)
    .join(', ')
}

function summarizeUniqueRoleValues(
  values: Array<string | null | undefined>,
): { count: number; values: string[] } {
  const byNormalized = new Map<string, string>()
  values.forEach((value) => {
    const normalized = normalizeCurateAuditStopName(value ?? undefined)
    if (!normalized || byNormalized.has(normalized)) {
      return
    }
    byNormalized.set(normalized, value?.trim() ?? normalized)
  })
  return {
    count: byNormalized.size,
    values: [...byNormalized.values()],
  }
}

function formatSurpriseHighlightDiagnosticRow(params: {
  artifactId: string
  highlight: string | null | undefined
  safetyState: SurpriseArtifactSafetyState
  family?: string | null
  directionId?: string | null
  sameHighlight?: boolean | null
  score?: number | null
  roleOverlapCount?: number | null
  orderingReason?: string | null
}): string {
  const {
    artifactId,
    highlight,
    safetyState,
    family = null,
    directionId = null,
    sameHighlight = null,
    score = null,
    roleOverlapCount = null,
    orderingReason = null,
  } = params
  return [
    `artifactId=${artifactId}`,
    `highlight=${highlight?.trim() || 'n/a'}`,
    `safetyState=${safetyState}`,
    `family=${family ?? 'n/a'}`,
    `directionId=${directionId ?? 'n/a'}`,
    `sameHighlight=${sameHighlight == null ? 'n/a' : String(sameHighlight)}`,
    `score=${score == null ? 'n/a' : score.toFixed(3)}`,
    `roleOverlapCount=${roleOverlapCount == null ? 'n/a' : String(roleOverlapCount)}`,
    `orderingReason=${orderingReason ?? 'n/a'}`,
  ].join('|')
}

function computeStorySpineRoleOverlap(params: {
  currentStorySpine: Pick<ContractEntryArtifact['storySpine'], 'start' | 'highlight' | 'windDown'> | null
  candidateStorySpine: Pick<ContractEntryArtifact['storySpine'], 'start' | 'highlight' | 'windDown'>
}): {
  sameStart: boolean
  sameHighlight: boolean
  sameWindDown: boolean
  roleOverlapCount: number
} {
  const { currentStorySpine, candidateStorySpine } = params
  const sameStart =
    normalizeCurateAuditStopName(candidateStorySpine.start) ===
    normalizeCurateAuditStopName(currentStorySpine?.start)
  const sameHighlight =
    normalizeCurateAuditStopName(candidateStorySpine.highlight) ===
    normalizeCurateAuditStopName(currentStorySpine?.highlight)
  const sameWindDown =
    normalizeCurateAuditStopName(candidateStorySpine.windDown) ===
    normalizeCurateAuditStopName(currentStorySpine?.windDown)
  return {
    sameStart,
    sameHighlight,
    sameWindDown,
    roleOverlapCount: [sameStart, sameHighlight, sameWindDown].filter(Boolean).length,
  }
}

function computeVisibleNightDifferenceScore(
  current: {
    routeTitle?: string
    routeSummary?: string
    flavorLine?: string
    traits?: string[]
    proofLines?: string[]
    districtAnchorLine?: string
    stops?: string[]
    stopVenueIds?: string[]
  },
  candidate: {
    routeTitle?: string
    routeSummary?: string
    flavorLine?: string
    traits?: string[]
    proofLines?: string[]
    districtAnchorLine?: string
    stops?: string[]
    stopVenueIds?: string[]
  },
): number {
  const normalize = (value?: string): string =>
    value
      ?.trim()
      .toLowerCase()
      .replace(/\s+/g, ' ') ?? ''
  const normalizeStops = (stops?: string[]): string[] =>
    (stops ?? [])
      .map((stop) => normalize(stop))
      .filter((stop) => stop.length > 0)
  const normalizeList = (values?: string[]): string[] =>
    (values ?? [])
      .map((value) => normalize(value))
      .filter((value) => value.length > 0)
  const scoreScalarDifference = (left?: string, right?: string, weight = 1): number =>
    normalize(left) !== normalize(right) ? weight : 0
  const scoreListDifference = (left?: string[], right?: string[], weight = 1): number => {
    const leftValues = normalizeList(left)
    const rightValues = normalizeList(right)
    const maxCount = Math.max(leftValues.length, rightValues.length)
    let listScore = 0
    for (let index = 0; index < maxCount; index += 1) {
      if ((leftValues[index] ?? '') !== (rightValues[index] ?? '')) {
        listScore += weight
      }
    }
    return listScore
  }
  const currentStops = normalizeStops(current.stops)
  const candidateStops = normalizeStops(candidate.stops)
  let score =
    scoreScalarDifference(current.routeTitle, candidate.routeTitle) +
    scoreScalarDifference(current.routeSummary, candidate.routeSummary) +
    scoreScalarDifference(current.flavorLine, candidate.flavorLine) +
    scoreListDifference(current.traits, candidate.traits) +
    scoreListDifference(current.proofLines, candidate.proofLines) +
    scoreScalarDifference(current.districtAnchorLine, candidate.districtAnchorLine, 2) +
    scoreListDifference(current.stopVenueIds, candidate.stopVenueIds)

  const maxStopCount = Math.max(currentStops.length, candidateStops.length)
  for (let index = 0; index < maxStopCount; index += 1) {
    if ((currentStops[index] ?? '') !== (candidateStops[index] ?? '')) {
      score += 1
    }
  }

  return score
}

