function getCurateQualificationStatus(
  preflight: CuratePreviewCommitabilityState | undefined,
  qualification: ContractEntryArtifact['qualification'] | undefined = undefined,
): CurateVisibleCardModel['qualificationStatus'] {
  // Side-map preflight remains authoritative. Artifact qualification is read-only
  // fallback for low-risk status derivation when preflight state is missing.
  const effectiveQualification = preflight ?? qualification
  if (!effectiveQualification) {
    return 'unchecked'
  }
  if (effectiveQualification.status === 'checking') {
    return 'checking'
  }
  if (
    effectiveQualification.status === 'committable' &&
    effectiveQualification.approvedRefinementEntryPayload
  ) {
    return 'qualified'
  }
  if (effectiveQualification.failureKind === 'runtime_error') {
    return 'runtime_error'
  }
  return 'rejected'
}

function buildArtifactByIdIndex(
  artifacts: ContractEntryArtifact[],
): Map<string, ContractEntryArtifact> {
  return new Map(artifacts.map((artifact) => [artifact.id, artifact] as const))
}

function buildArtifactsByDirectionIdIndex(
  artifacts: ContractEntryArtifact[],
): Map<string, ContractEntryArtifact[]> {
  const grouped = new Map<string, ContractEntryArtifact[]>()
  artifacts.forEach((artifact) => {
    const directionId = artifact.selection.directionId
    if (!directionId) {
      return
    }
    const existing = grouped.get(directionId)
    if (existing) {
      existing.push(artifact)
      return
    }
    grouped.set(directionId, [artifact])
  })
  return grouped
}

function selectArtifactResolutionSources(params: {
  isCurateWrapperActive: boolean
  curatePrimarySelectableArtifactById: Map<string, ContractEntryArtifact>
  curatePrimarySelectableArtifactsByDirectionId: Map<string, ContractEntryArtifact[]>
  candidateRouteArtifactByIdForDisplay: Map<string, ContractEntryArtifact>
  candidateRouteArtifactsByDirectionIdForDisplay: Map<string, ContractEntryArtifact[]>
}): {
  artifactById: Map<string, ContractEntryArtifact>
  artifactsByDirectionId: Map<string, ContractEntryArtifact[]>
  subsetMode: 'curate_primary_selectable' | 'visible_for_display'
} {
  const {
    isCurateWrapperActive,
    curatePrimarySelectableArtifactById,
    curatePrimarySelectableArtifactsByDirectionId,
    candidateRouteArtifactByIdForDisplay,
    candidateRouteArtifactsByDirectionIdForDisplay,
  } = params

  if (isCurateWrapperActive) {
    return {
      artifactById: curatePrimarySelectableArtifactById,
      artifactsByDirectionId: curatePrimarySelectableArtifactsByDirectionId,
      subsetMode: 'curate_primary_selectable',
    }
  }

  return {
    artifactById: candidateRouteArtifactByIdForDisplay,
    artifactsByDirectionId: candidateRouteArtifactsByDirectionIdForDisplay,
    subsetMode: 'visible_for_display',
  }
}

function resolveFinalRouteStopGeography(finalRoute: RuntimeRouteArtifact | null | undefined): string | null {
  if (!finalRoute?.stops.length) {
    return null
  }
  const counts = new Map<string, { label: string; count: number }>()
  finalRoute.stops.forEach((stop) => {
    const label = stop.neighborhood?.trim()
    if (!label) {
      return
    }
    const key = label.toLowerCase()
    const current = counts.get(key)
    if (current) {
      current.count += 1
    } else {
      counts.set(key, { label, count: 1 })
    }
  })
  return [...counts.values()].sort(
    (left, right) => right.count - left.count || left.label.localeCompare(right.label),
  )[0]?.label ?? null
}

function resolveFinalRouteDisplayLocation(
  finalRoute: RuntimeRouteArtifact | null | undefined,
  fallbackLocation?: string | null,
): string | null {
  return (
    resolveFinalRouteStopGeography(finalRoute) ??
    finalRoute?.location?.trim() ??
    fallbackLocation?.trim() ??
    null
  )
}

function buildFinalRouteClusterConfirmation(
  finalRoute: RuntimeRouteArtifact | null | undefined,
  fallbackLocation?: string | null,
): string | null {
  if (!finalRoute) {
    return null
  }
  const location = resolveFinalRouteDisplayLocation(finalRoute, fallbackLocation)
  const highlight =
    finalRoute.stops.find((stop) => stop.role === 'highlight')?.displayName?.trim() ??
    finalRoute.routeHeadline?.trim()
  if (highlight && location) {
    return `${highlight} anchors the selected route in ${location}.`
  }
  return location ? `Selected route geography: ${location}.` : null
}

type CoffeeBooksCommittedRouteSummaryAdmission =
  | {
      status: 'accepted'
      semanticRepresentationStatus: 'represented'
      evidenceCount: number
      matchedEvidence: StarterSemanticEvidenceMatch[]
      rejectedReason: null
    }
  | {
      status: 'rejected'
      semanticRepresentationStatus: 'missing'
      evidenceCount: 0
      matchedEvidence: StarterSemanticEvidenceMatch[]
      rejectedReason: typeof coffeeBooksSemanticRepresentationMissingReason
    }
  | {
      status: 'not_applicable'
      semanticRepresentationStatus: null
      evidenceCount: null
      matchedEvidence: []
      rejectedReason: null
    }

function toCoffeeBooksSemanticPosition(role: UserStopRole): BuiltScenarioStop['position'] {
  if (role === 'start') {
    return 'start'
  }
  if (role === 'highlight') {
    return 'highlight'
  }
  if (role === 'windDown') {
    return 'windDown'
  }
  return 'mid'
}

function evaluateCoffeeBooksCommittedRouteSummaryAdmission(params: {
  isPublicSurface: boolean
  isCurateWrapperActive: boolean
  starterPackId: string | null
  finalRoute: RuntimeRouteArtifact | null
  itinerary?: Itinerary | null
}): CoffeeBooksCommittedRouteSummaryAdmission {
  if (
    !params.isPublicSurface ||
    !params.isCurateWrapperActive ||
    params.starterPackId !== 'coffee-books'
  ) {
    return {
      status: 'not_applicable',
      semanticRepresentationStatus: null,
      evidenceCount: null,
      matchedEvidence: [],
      rejectedReason: null,
    }
  }
  if (!params.finalRoute) {
    return {
      status: 'rejected',
      semanticRepresentationStatus: 'missing',
      evidenceCount: 0,
      matchedEvidence: [],
      rejectedReason: coffeeBooksSemanticRepresentationMissingReason,
    }
  }
  const itineraryStopByRole = new Map(
    (params.itinerary?.stops ?? []).map((stop) => [stop.role, stop] as const),
  )
  const representation = buildCoffeeBooksSemanticRepresentationFromRouteStops(
    (params.finalRoute?.stops ?? []).map((stop) => {
      const itineraryStop = itineraryStopByRole.get(stop.role)
      return {
        venueId: stop.venueId,
        name: stop.displayName,
        position: toCoffeeBooksSemanticPosition(stop.role),
        evidenceParts: [
          { field: 'displayName', value: stop.displayName },
          { field: 'venueName', value: itineraryStop?.venueName },
          { field: 'venueCategory', value: itineraryStop?.category },
          { field: 'venueSubcategory', value: itineraryStop?.subcategory },
          { field: 'tag', value: itineraryStop?.tags },
        ],
      }
    }),
  )
  if (representation.status === 'represented') {
    return {
      status: 'accepted',
      semanticRepresentationStatus: 'represented',
      evidenceCount: representation.evidence.length,
      matchedEvidence: representation.matchedEvidence?.filter((match) => match.admissible) ?? [],
      rejectedReason: null,
    }
  }
  return {
    status: 'rejected',
    semanticRepresentationStatus: 'missing',
    evidenceCount: 0,
    matchedEvidence: representation.matchedEvidence ?? [],
    rejectedReason: coffeeBooksSemanticRepresentationMissingReason,
  }
}

