    setSelectedIdReconciled(false)
    setCuratePreviewCommitabilityByArtifactId({})
    setCurateQualificationCacheHitByArtifactId({})
    setCurateCommittedRouteFallbackState(null)
    setCurateRefinementEntryPayload(null)
