    setRejectedStopRoles([])
    setPlan(undefined)
    updateFinalRoute(null)
    setHasRevealed(false)
    setPreviewSwap(undefined)
    setExpandedRole(null)
    setAppliedSwapRole(null)
    setNearbySummaryByRole({})
